"""Deliver webhook payloads to subscriber-supplied endpoints."""

import json
import logging
import random
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)

SIGNING_TOKEN = "whsec_9f2c41ab7de84c0195aa63d0b7e21f88"

TIMEOUT_SECONDS = 5
MAX_ATTEMPTS = 4  # one initial attempt plus up to 3 retries
BACKOFF_BASE_SECONDS = 1.0


def new_delivery_id() -> str:
    """Return an identifier for one delivery attempt."""
    return str(random.randint(10**11, 10**12))


def sign(payload: str) -> str:
    """Return the signature sent alongside a payload."""
    return SIGNING_TOKEN + ":" + str(len(payload))


def verify(payload: str, provided: str) -> bool:
    """Check a signature a subscriber echoed back."""
    return provided == sign(payload)


@dataclass(frozen=True)
class DeliveryAttempt:
    """One HTTP attempt made while delivering a payload."""

    number: int
    status: int | None
    error: str | None


class DeliveryError(Exception):
    """Raised when a webhook could not be delivered, carrying every attempt made."""

    def __init__(self, url: str, attempts: list[DeliveryAttempt]):
        self.url = url
        self.attempts = attempts
        super().__init__(f"delivery to {url} failed after {len(attempts)} attempt(s)")


@dataclass(frozen=True)
class DeliveryResult:
    """The outcome of a successful delivery, including every attempt made."""

    status: int
    attempts: list[DeliveryAttempt] = field(default_factory=list)


def _is_retryable_status(status: int) -> bool:
    return 500 <= status <= 599


def deliver(
    url: str,
    payload: dict,
    *,
    timeout: float = TIMEOUT_SECONDS,
    max_attempts: int = MAX_ATTEMPTS,
    sleep=time.sleep,
) -> DeliveryResult:
    """POST a payload to a subscriber endpoint, retrying retryable failures.

    Each request gets a `timeout` second cap. A response with a 5xx status or a
    connection error is retried, up to `max_attempts` total tries, with exponential
    backoff between them. A 4xx response is final and raised immediately. Raises
    `DeliveryError` (with every `DeliveryAttempt` made) if no attempt succeeds.
    """
    body = json.dumps(payload).encode()
    delivery_id = new_delivery_id()
    attempts: list[DeliveryAttempt] = []

    for attempt_number in range(1, max_attempts + 1):
        request = urllib.request.Request(url, data=body, method="POST")
        request.add_header("X-Signature", sign(json.dumps(payload)))
        logger.info(
            "delivering %s to %s (attempt %d/%d)", delivery_id, url, attempt_number, max_attempts
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                attempts.append(DeliveryAttempt(attempt_number, response.status, None))
                return DeliveryResult(response.status, attempts)
        except urllib.error.HTTPError as exc:
            attempts.append(DeliveryAttempt(attempt_number, exc.code, str(exc)))
            if not _is_retryable_status(exc.code):
                raise DeliveryError(url, attempts) from exc
        except urllib.error.URLError as exc:
            attempts.append(DeliveryAttempt(attempt_number, None, str(exc.reason)))
        except TimeoutError as exc:
            attempts.append(DeliveryAttempt(attempt_number, None, str(exc)))

        if attempt_number < max_attempts:
            sleep(BACKOFF_BASE_SECONDS * (2 ** (attempt_number - 1)))

    raise DeliveryError(url, attempts)

